import{_ as e,c as r,o as t,a as s}from"./app.19f3f8f0.js";const g=JSON.parse('{"title":"Episode 1 — Never lose a lead in the comments","description":"Why comment automation exists and how ReplyBridge fits a real shop or creator workflow.","frontmatter":{"title":"Episode 1 — Never lose a lead in the comments","description":"Why comment automation exists and how ReplyBridge fits a real shop or creator workflow."},"headers":[{"level":2,"title":"What you should remember","slug":"what-you-should-remember","link":"#what-you-should-remember","children":[]},{"level":2,"title":"Your next step","slug":"your-next-step","link":"#your-next-step","children":[]},{"level":2,"title":"Series","slug":"series","link":"#series","children":[]}],"relativePath":"replybridge/series/01-never-lose-a-lead-in-comments.md"}'),o={name:"replybridge/series/01-never-lose-a-lead-in-comments.md"},a=s('<h1 id="episode-1-—-never-lose-a-lead-in-the-comments" tabindex="-1">Episode 1 — Never lose a lead in the comments <a class="header-anchor" href="#episode-1-—-never-lose-a-lead-in-the-comments" aria-hidden="true">#</a></h1><p>Someone comments <strong>“How much?”</strong> or <strong>“Link?”</strong> on your post. If you answer late—or miss it—they may already be gone.</p><p><strong>ReplyBridge</strong> helps you respond <strong>right away</strong>: a <strong>private DM</strong> with your price, link, or next step, and optionally a <strong>short public reply</strong> so others see the answer too.</p><hr><h2 id="what-you-should-remember" tabindex="-1">What you should remember <a class="header-anchor" href="#what-you-should-remember" aria-hidden="true">#</a></h2><ol><li><strong>Speed feels like care</strong> — Fast first replies build trust.</li><li><strong>Same question, many people</strong> — Automation saves you from copy-paste burnout.</li><li><strong>You stay in control</strong> — You write the message; the app sends it when <strong>your</strong> rules match.</li></ol><hr><h2 id="your-next-step" tabindex="-1">Your next step <a class="header-anchor" href="#your-next-step" aria-hidden="true">#</a></h2><p>If you haven’t installed the app yet, use the full walkthrough:</p><p>👉 <strong><a href="/replybridge/getting-started">Get started — install &amp; set up</a></strong></p><hr><h2 id="series" tabindex="-1">Series <a class="header-anchor" href="#series" aria-hidden="true">#</a></h2><ul><li><strong>Next:</strong> <a href="/replybridge/series/02-dm-or-public-reply">Episode 2 — DM or public reply?</a></li><li><strong>All episodes:</strong> <a href="/replybridge/series/">Instagram mini-series</a></li></ul>',13),n=[a];function i(l,h,d,p,m,u){return t(),r("div",null,n)}const y=e(o,[["render",i]]);export{g as __pageData,y as default};
